for kind,file,title,subtitle in [('story','story.html','Cốt truyện & Lore','Đọc tuyến xuyên suốt, khám phá vùng đất và hiểu những người sống trong thế giới.'),('visual','visual-design.html','Thiết kế hình ảnh','Bản đồ, nhân vật, giao diện và asset — tập trung bản hiện hành, có ghi rõ giới hạn.')]:
 activeStory=' aria-current="page"' if kind=='story' else '';activeVisual=' aria-current="page"' if kind=='visual' else ''
 doc=f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101f19"><title>{title} · Ẩn Thành</title><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/design-hub.css?v=20261022-1"></head><body data-hub="{kind}"><header class="top"><a class="brand" href="/roadmap.html"><img src="/favicon.svg" alt="">ẨN THÀNH</a><nav aria-label="Các trang thiết kế"><a href="/roadmap.html">Roadmap & Checklist</a><a href="/story.html"{activeStory}>Cốt truyện & Lore</a><a href="/visual-design.html"{activeVisual}>Thiết kế hình ảnh</a></nav></header><main><section class="hero"><div><span class="eyebrow">KHÔNG GIAN THIẾT KẾ · NỘI BỘ</span><h1>{title}</h1><p>{subtitle}</p><div class="actions" id="hero-actions"></div></div><img src="/design-preview/elarion-map-r002/world-expanded__concept_r002.png" alt="Concept Elarion và mười vùng đất dự phòng"></section><div class="notice" id="scope-note"></div><section class="stats" id="stats" aria-label="Phạm vi tài liệu"></section><section><div class="section-title"><h2 id="section-title"></h2><small id="result-count"></small></div><div class="toolbar"><input id="search" type="search" aria-label="Tìm tài liệu hoặc bản vẽ" placeholder="Tìm tên, chủ đề, nhân vật…"></div><div class="filters" id="filters" aria-label="Lọc nội dung"></div><div id="catalog" class="cards"><div class="loading">Đang mở thư viện…</div></div></section><section class="reader" id="reader" hidden><div class="reader-bar"><span id="reader-label"></span><div class="actions"><button class="btn secondary" id="download">↓ Markdown</button><button class="btn secondary" id="print">In / PDF</button><button class="btn secondary" id="close-reader">Đóng bài</button></div></div><div id="reader-content"></div></section><section><div class="section-title"><h2 id="library-title"></h2><small id="library-count"></small></div><div id="library" class="doc-list"></div></section></main><footer>ẨN THÀNH · Tài liệu và hình thiết kế, chưa phải chức năng đã tích hợp trong game. Nội dung lấy từ Markdown và bản vẽ lưu trong dự án.</footer><dialog id="image-dialog"><div class="modal-top"><strong id="image-title"></strong><button class="btn secondary" id="close-image">Đóng ×</button></div><img id="large-image" alt=""><p id="image-description"></p><div class="modal-links" id="image-links"></div></dialog><script type="module" src="/design-hub.js?v=20261022-1"></script></body></html>'''
 (root/file).write_text(doc,encoding='utf-8')
print('Created story.html and visual-design.html')
